 		return -EFAULT;
 	i += len;

 	max = count - i;
 	len = count_trail_chars(&user_buffer[i], max);
 	if (len < 0)
 		return len;

 	i += len;

 	if (debug) {
 		size_t copy = min_t(size_t, count, 1023);
